# Distribution / iteration token. BUMP THIS to a new value every time you hand
# the file out for a fresh round of annotation (e.g. "v3" -> "v4"). It is the one
# knob that isolates each round from the last, on BOTH sides:
#   * Server logs are written to annotation_<ITERATION>_<id>_<name>.json, so a new
#     round starts a brand-new file instead of reopening the previous round's — and
#     "Download my log" hands back that new file.
#   * The browser's per-person state (identity, the unsaved-save queue, last clip
#     position, and type-ahead history) is keyed by this token, so a RETURNING
#     annotator opening the same URL doesn't inherit last round's queue or cursor.
# The value is slugified for filenames, so letters/digits are safest (spaces and
# punctuation collapse to "_"). Annotators do nothing but run the file.
ITERATION = "v7"

# Secondary backup directory — every save is also written here so annotations
# survive regardless of where --notes-dir points.
BACKUP_NOTES_DIR = Path("/projectnb/ivc-ml/maxwh/code/v3/senses/annotations")

# First-frame poster JPEGs (so the grid renders as a still contact sheet without
# downloading any video) are generated lazily, in memory, on the first request for
# each clip and cached in RAM — see VideoIndex.poster_bytes_for_id. Nothing is
# written to disk, so the whole app ships as this single file: distribute studio.py
# on its own and the thumbnails just work (as long as ffmpeg is on PATH). The cache
# is an LRU capped at POSTER_CACHE_MAX entries (~20-40 KB each) so a very large clip
# set can't exhaust memory; evicted posters are simply regenerated on demand.
POSTER_CACHE_MAX = 1500

# A grid page shows ~100 tiles and each tile requests its poster at once; every
# poster that isn't cached spawns one ffmpeg process. Left unbounded that forks
# dozens of decoders simultaneously, which pins the CPU and RAM of the machine —
# on a shared login node that is exactly what trips the resource watchdog and
# drops the SSH/VS Code session ("Attempting to reconnect"). Cap how many ffmpeg
# runs can be in flight at once so poster generation degrades to a queue instead
# of a fork bomb; the browser only opens a handful of connections at a time
# anyway, so this stays responsive.
POSTER_MAX_WORKERS = 2

# Width the first-frame poster is scaled to; grid tiles render well under this and
# it keeps each JPEG around 15-40 KB.
POSTER_WIDTH = 400

