# Clip assignment
COPIES_PER_CLIP = 3

# All 9 annotators are primary for this round.
PRIMARY_ANNOTATOR_IDS = (1, 2, 3, 4, 5, 6, 7, 8, 9)
SECONDARY_ANNOTATOR_IDS = ()
SECONDARY_CLIPS_PER_PERSON = 0


def login_roster() -> dict[int, str]:
    """The people the login dropdown offers — the primaries only. With the
    secondary sample wiped, listing a secondary would hand them a login that
    opens an empty gallery. ANNOTATORS itself stays complete so names on
    existing annotation files and exports still resolve."""
    return {pid: ANNOTATORS[pid] for pid in PRIMARY_ANNOTATOR_IDS if pid in ANNOTATORS}

# --- The curated clip set -------------------------------------------------
# All 850 clips are labeled; no sub-sampling needed.
# Strata: clip_id 1-400 = babyview_random, 401-850 = saycam_random.
CURATED_CLIP_COUNT = 850
CLIP_STRATA = ((1, 850),)

# Any fixed value works; changing it reshuffles who labels what. Keep it constant
# so re-running the server always produces the same predetermined assignment.
ASSIGNMENT_SEED = 20240708


def _even_stride(start: int, size: int, want: int) -> list[int]:
    """``want`` indices spread evenly across ``[start, start + size)``."""
    if want <= 0 or size <= 0:
        return []
    want = min(want, size)
    return [start + (i * size) // want for i in range(want)]


def curated_clip_indices(num_clips: int) -> list[int]:
    """0-based indices of the CURATED_CLIP_COUNT clips the primaries label, drawn
    in equal measure from each stratum in CLIP_STRATA and returned in ascending
    order. When the loaded clip list doesn't match the documented strata layout
    (a custom exemplars file, say), falls back to one even stride over the whole
    list so the count still comes out right."""
    want = min(CURATED_CLIP_COUNT, num_clips)
    strata = [(lo - 1, hi - lo + 1) for lo, hi in CLIP_STRATA]
    if not strata or sum(size for _, size in strata) != num_clips:
        return _even_stride(0, num_clips, want)
    picks: list[int] = []
    for pos, (start, size) in enumerate(strata):
        # Hand the remainder to the earliest strata so the total is exactly `want`.
        share = want // len(strata) + (1 if pos < want % len(strata) else 0)
        picks.extend(_even_stride(start, size, share))
    return sorted(picks)


def primary_load(num_clips: int) -> int:
    """Clips handed to each primary annotator. ``num_clips`` here is the size of
    the curated set, not the whole batch. The primaries share
    ``num_clips * COPIES_PER_CLIP`` labelling slots evenly, so this is that total
    rounded up: with 150 curated clips at 3 copies over 7 primaries, 450/7 -> 65,
    and build_assignments' balancing lands everyone on 64 or 65."""
    if not PRIMARY_ANNOTATOR_IDS:
        return 0
    return -(-num_clips * COPIES_PER_CLIP // len(PRIMARY_ANNOTATOR_IDS))


def build_assignments(num_clips: int, num_annotators: int) -> dict[int, list[int]]:
    """Return ``{annotator_index: [clip_index, ...]}`` implementing the
    primary/secondary split described above. Annotator indices are 0-based
    (login ID ``n`` maps to index ``n - 1``). Each clip list is returned in
    ascending clip-index order so a person's clips paginate in the same order
    they appear in the gallery. ``num_annotators`` is accepted for backward
    compatibility but the roster is fixed by PRIMARY/SECONDARY_ANNOTATOR_IDS."""
    buckets: dict[int, list[int]] = {}
    rng = random.Random(ASSIGNMENT_SEED)

    # --- Primary annotators: even, COPIES_PER_CLIP-deep coverage of the curated
    #     set (see curated_clip_indices). Handing each clip to whoever has the
    #     most capacity left keeps loads within one clip of each other, and —
    #     because the curated set draws equally from the three 100-clip strata —
    #     also gives every primary a ~1/3-1/3-1/3 mix of them.
    curated = curated_clip_indices(num_clips)
    copies = min(COPIES_PER_CLIP, len(PRIMARY_ANNOTATOR_IDS))
    remaining = {pid: primary_load(len(curated)) for pid in PRIMARY_ANNOTATOR_IDS}
    for pid in PRIMARY_ANNOTATOR_IDS:
        buckets[pid - 1] = []
    for clip in curated:
        order = sorted(PRIMARY_ANNOTATOR_IDS, key=lambda p: (-remaining[p], rng.random()))
        for pid in order[:copies]:
            buckets[pid - 1].append(clip)
            remaining[pid] -= 1

    # --- Secondary annotators: an independent random sample of the whole set.
    #     With SECONDARY_CLIPS_PER_PERSON at 0 this is an empty list for each of
    #     them — they still need a bucket, because a missing one would send them
    #     down items_for_annotator's "unknown ID" path and serve the full batch.
    sample_n = min(SECONDARY_CLIPS_PER_PERSON, num_clips)
    for sid in SECONDARY_ANNOTATOR_IDS:
        buckets[sid - 1] = sorted(rng.sample(range(num_clips), sample_n))

    for a in buckets:
        buckets[a].sort()
    return buckets


# ---------------------------------------------------------------------------
# Landing groups
#
# v5 paired four annotators into two GROUPS ("aj" = Arjun + Jason, "mk" = Michael
# + Karthik) that each saw half of the 60-clip batch, so a group's two members
# could be compared for agreement. v6 drops that: the primary/secondary split
# above already gives every one of the 300 clips exactly COPIES_PER_CLIP
# independent primary labels, so agreement comes out of the main assignment and a
# separate group override would only pull IDs 3/4/5/8 (all primaries) off their
# slices and break the even coverage. Kept as no-ops so callers still resolve.
ANNOTATION_GROUPS: tuple[tuple[str, tuple[int, ...]], ...] = ()


def group_for_annotator(annotator_id: int | None) -> str | None:
    """Return the group key an annotator belongs to, or None. With
    ANNOTATION_GROUPS empty this is always None and every annotator falls through
    to their build_assignments slice."""
    if not annotator_id:
        return None
    for key, members in ANNOTATION_GROUPS:
        if annotator_id in members:
            return key
    return None


def build_group_clips(num_clips: int) -> dict[str, list[int]]:
    """Return ``{group_key: [clip_index, ...]}`` — the clips each group annotates.
    Empty for v6 (see ANNOTATION_GROUPS); restore a mapping here to carve out a
    shared clip set for a pair of annotators again."""
    return {}


