@dataclass(frozen=True)
class VideoItem:
    id: int
    clip_id: int
    rel: str
    name: str
    size: int
    mtime: float


class VideoIndex:
    """Loads a fixed, ordered list of videos from an exemplars file instead of
    scanning a directory. The exemplars file is JSON-lines, one object per line
    with a ``clip_id`` (the clip number) and a ``name`` (the file name). The
    files are served from ``root``. Order is preserved from the file. With the
    embedded 300-clip batch the primary/secondary split (see build_assignments)
    gives each of the 7 primaries 64-65 clips out of the curated 150 — every
    curated clip covered by exactly COPIES_PER_CLIP (3) of them — and each
    secondary nothing at all (SECONDARY_CLIPS_PER_PERSON is 0)."""

    def __init__(
        self,
        root: Path,
        exemplars: Path | None,
    ) -> None:
        self.root = root.expanduser().resolve()
        self.exemplars = exemplars.expanduser() if exemplars is not None else None
        # In-memory poster cache (see poster_bytes_for_id). Maps video_id -> JPEG
        # bytes, or b"" for clips whose poster couldn't be produced (missing file
        # or ffmpeg failure) so we don't retry them on every tile. An OrderedDict
        # gives cheap LRU eviction; _poster_lock guards it against the threaded
        # server's concurrent requests. _ffmpeg is resolved once and reused.
        self._poster_cache: "OrderedDict[int, bytes]" = OrderedDict()
        self._poster_lock = threading.Lock()
        self._ffmpeg = shutil.which("ffmpeg")
        # Bounds concurrent ffmpeg poster renders (see POSTER_MAX_WORKERS) so a
        # burst of tile requests can't fork one decoder per tile.
        self._ffmpeg_slots = threading.Semaphore(POSTER_MAX_WORKERS)
        self._items: list[VideoItem] = []
        # {annotator_index: [clip_index, ...]} produced by build_assignments once
        # the clip list is known. Keyed by 0-based annotator index.
        self._assignments: dict[int, list[int]] = {}
        # {group_key: [clip_index, ...]} for the two landing groups (see
        # build_group_clips); both members of a group share the same list.
        self._group_clips: dict[str, list[int]] = {}
        self._lock = threading.Lock()

    @property
    def items(self) -> list[VideoItem]:
        return self._items

    def items_for_annotator(self, annotator_id: int | None) -> list[VideoItem]:
        """The clips a given annotator is responsible for, in gallery order.
        ``annotator_id`` is the 1-based login ID. Landing annotators get their
        GROUP's clip set (both members of a group see the same clips); everyone
        else falls back to their build_assignments slice, and an unknown ID (or
        no one logged in, e.g. exports) gets the full list."""
        if not annotator_id:
            return self._items
        group = group_for_annotator(annotator_id)
        if group is not None:
            clip_indices = self._group_clips.get(group)
            if clip_indices is not None:
                return [self._items[i] for i in clip_indices]
        clip_indices = self._assignments.get(annotator_id - 1)
        if clip_indices is None:
            return self._items
        return [self._items[i] for i in clip_indices]

    def item_for_id(self, video_id: int) -> VideoItem | None:
        if video_id < 0 or video_id >= len(self._items):
            return None
        return self._items[video_id]

    def path_for_id(self, video_id: int) -> Path | None:
        item = self.item_for_id(video_id)
        if item is None:
            return None
        return (self.root / item.rel).resolve()

    def media_source_for_id(self, video_id: int) -> tuple[Path, Path] | None:
        """Return ``(file, base_dir)`` for the clip to stream: the original clip
        under ``root``. The base dir is returned so the caller can confine the
        path to it. Playback uses HTTP range requests, so it starts without any
        pre-transcoding step."""
        item = self.item_for_id(video_id)
        if item is None:
            return None
        return (self.root / item.rel), self.root

    def poster_bytes_for_id(self, video_id: int) -> bytes | None:
        """First-frame poster JPEG for a clip, generated on demand with ffmpeg and
        cached in memory (no files touch disk). Returns the JPEG bytes, or ``None``
        when no poster can be produced (unknown id, missing source, ffmpeg absent,
        or ffmpeg error) — the caller then serves an empty tile.

        Only *permanent* failures (ffmpeg absent or source missing) are memoized
        as ``b""`` so we never retry them; *transient* failures (ffmpeg timeout or
        error, common when many tiles contend for the POSTER_MAX_WORKERS slots at
        once) are NOT cached, so a later request re-renders instead of leaving the
        tile blank until restart. Successes are cached; the LRU is capped at
        POSTER_CACHE_MAX entries."""
        item = self.item_for_id(video_id)
        if item is None:
            return None

        with self._poster_lock:
            cached = self._poster_cache.get(video_id)
            if cached is not None:
                self._poster_cache.move_to_end(video_id)
                return cached or None

        data = self._render_poster(item)
        if data is None:
            # Transient failure — leave uncached so the next request retries.
            return None

        with self._poster_lock:
            # ``data`` is JPEG bytes (success) or b"" (permanent blank).
            self._poster_cache[video_id] = data
            self._poster_cache.move_to_end(video_id)
            while len(self._poster_cache) > POSTER_CACHE_MAX:
                self._poster_cache.popitem(last=False)
        return data or None

    def _render_poster(self, item: "VideoItem") -> bytes | None:
        """Run ffmpeg to grab the first frame as a scaled JPEG on stdout. Kept out
        of the locked section so concurrent tiles render in parallel. Returns:
        the JPEG bytes on success; ``b""`` for a *permanent* failure (ffmpeg
        absent or source not a file) that should be cached as a blank; ``None``
        for a *transient* failure (timeout / ffmpeg error) that should be retried
        rather than cached."""
        if self._ffmpeg is None:
            return b""
        src = self.root / item.rel
        if not src.is_file():
            return b""
        try:
            with self._ffmpeg_slots:
                result = subprocess.run(
                    [self._ffmpeg, "-nostdin", "-loglevel", "error",
                     "-i", str(src), "-frames:v", "1", "-q:v", "5",
                     "-vf", "scale=" + str(POSTER_WIDTH) + ":-2",
                     "-f", "image2pipe", "-vcodec", "mjpeg", "pipe:1"],
                    capture_output=True, timeout=60,
                )
        except (OSError, subprocess.SubprocessError):
            return None
        if result.returncode != 0 or not result.stdout:
            return None
        return result.stdout

    def load(self) -> None:
        if not self.root.exists():
            raise FileNotFoundError("Video directory does not exist: " + str(self.root))
        if not self.root.is_dir():
            raise NotADirectoryError("Video path is not a directory: " + str(self.root))

        started = time.time()
        if self.exemplars is not None:
            if not self.exemplars.exists():
                raise FileNotFoundError("Exemplars file does not exist: " + str(self.exemplars))
            print("Loading exemplars from " + str(self.exemplars) + " ...", flush=True)
            with self.exemplars.open("r", encoding="utf-8") as handle:
                lines = handle.readlines()
        else:
            print("Loading the embedded exemplar list ...", flush=True)
            lines = EXEMPLARS_DATA.splitlines()
        items = self._read_exemplars(lines)
        assignments = build_assignments(len(items), len(ANNOTATORS))
        group_clips = build_group_clips(len(items))
        with self._lock:
            self._items = items
            self._assignments = assignments
            self._group_clips = group_clips
        elapsed = time.time() - started
        print("Loaded " + format(len(items), ",") + " videos in " + format(elapsed, ".1f") + "s.", flush=True)

        missing = [item.rel for item in items if item.size == 0 and not (self.root / item.rel).exists()]
        if missing:
            print(
                "Warning: " + format(len(missing), ",") + " listed videos were not found under " + str(self.root),
                file=sys.stderr,
                flush=True,
            )

    def search(self, query: str, offset: int, limit: int, annotator_id: int | None = None) -> dict[str, Any]:
        query = query.strip().lower()
        offset = max(offset, 0)
        limit = min(max(limit, 1), 500)

        pool = self.items_for_annotator(annotator_id)
        if query:
            matched = [item for item in pool if query in item.rel.lower()]
        else:
            matched = pool

        page = matched[offset : offset + limit]
        return {
            "total": len(matched),
            "offset": offset,
            "limit": limit,
            "videos": [self._public_item(item) for item in page],
        }

    def stats(self) -> dict[str, Any]:
        total_bytes = sum(item.size for item in self._items)
        return {
            "root": str(self.root),
            "count": len(self._items),
            "total_bytes": total_bytes,
            "exemplars": str(self.exemplars) if self.exemplars is not None else "embedded list",
        }

    def _read_exemplars(self, lines: list[str]) -> list[VideoItem]:
        source = str(self.exemplars) if self.exemplars is not None else "embedded list"
        rows: list[tuple[int, str]] = []
        for line_no, raw in enumerate(lines, 1):
            line = raw.strip()
            if not line:
                continue
            try:
                entry = json.loads(line)
            except json.JSONDecodeError:
                print(
                    "Skipping malformed line " + str(line_no) + " in " + source,
                    file=sys.stderr,
                    flush=True,
                )
                continue
            if not isinstance(entry, dict):
                continue
            name = clean_text(entry.get("name"), 512)
            if not name:
                continue
            clip_id = clamp_int(entry.get("clip_id"), -1, -1, 10**9)
            rows.append((clip_id, name))

        items: list[VideoItem] = []
        for i, (clip_id, name) in enumerate(rows):
            rel = name  # the exemplar files live directly inside root
            try:
                stat = (self.root / rel).stat()
                size = stat.st_size
                mtime = stat.st_mtime
            except OSError:
                size = 0
                mtime = 0.0
            items.append(
                VideoItem(
                    id=i,
                    clip_id=clip_id,
                    rel=rel,
                    name=posixpath.basename(rel),
                    size=size,
                    mtime=mtime,
                )
            )
        return items

    @staticmethod
    def _public_item(item: VideoItem) -> dict[str, Any]:
        return {
            "id": item.id,
            "clip_id": item.clip_id,
            "name": item.name,
            "rel": item.rel,
            "size": item.size,
            "mtime": item.mtime,
            "url": "media/" + str(item.id) + "/" + urllib.parse.quote(item.name),
            "poster": "poster/" + str(item.id),
        }


def slugify(value: str) -> str:
    """Turn an annotator name into a safe file-name fragment, e.g.
    "Sarah Zhou" -> "sarah_zhou". Empty when nothing usable remains."""
    return re.sub(r"[^A-Za-z0-9]+", "_", (value or "").strip()).strip("_").lower()


class AnnotationStore:
    def __init__(self, path: Path, txt_path: Path, root: Path, annotator: dict[str, Any] | None = None, backup_path: Path | None = None) -> None:
        self.path = path.expanduser()
        self.txt_path = txt_path.expanduser()
        self.backup_path = backup_path.expanduser() if backup_path else None
        self.root = str(root.expanduser().resolve())
        self._items: dict[str, dict[str, Any]] = {}
        # Each store belongs to exactly one annotator (its own file). The owner is
        # fixed at construction so a person's log always records who produced it.
        self.annotator: dict[str, Any] | None = annotator
        self._lock = threading.Lock()

    def load(self) -> None:
        try:
            if not self.path.exists():
                # Create an empty annotation file immediately so it always exists;
                # every subsequent save writes into this same file.
                with self._lock:
                    self._items = {}
                    self._persist_locked()
                return
            with self.path.open("r", encoding="utf-8") as handle:
                payload = json.load(handle)
            if isinstance(payload, list):
                rows = payload
            elif isinstance(payload, dict):
                # Keep the fixed owner set at construction; only fall back to the
                # file's own annotator when this store has no owner assigned.
                if self.annotator is None:
                    self.annotator = load_annotator(payload)
                raw_items = payload.get("items")
                if raw_items is None:
                    raw_items = payload.get("annotations", {})
                if isinstance(raw_items, list):
                    rows = raw_items
                elif isinstance(raw_items, dict):
                    rows = list(raw_items.values())
                else:
                    rows = []
            else:
                rows = []

            loaded: dict[str, dict[str, Any]] = {}
            for row in rows:
                if not isinstance(row, dict):
                    continue
                record = self._normalize_record(row)
                if record["rel"]:
                    loaded[record["rel"]] = record
            with self._lock:
                self._items = loaded
        except (OSError, json.JSONDecodeError, TypeError, ValueError) as exc:
            print("Could not load smell selections: " + str(exc), file=sys.stderr, flush=True)

    def all(self) -> dict[str, Any]:
        with self._lock:
            records = list(self._items.values())
        records.sort(key=lambda row: float(row.get("updated_at", 0)), reverse=True)
        return {
            "root": self.root,
            "path": str(self.path),
            "txt_path": str(self.txt_path),
            "annotator": self.annotator,
            "count": len(records),
            "items": records,
        }

    def txt_body(self) -> str:
        with self._lock:
            return self._build_txt_locked()

    def save(self, payload: dict[str, Any], video_index: VideoIndex) -> dict[str, Any]:
        video_id = clamp_int(payload.get("id"), -1, -1, 10**9)
        item = video_index.item_for_id(video_id)
        rel = clean_text(payload.get("rel"), 4096)
        clip_id = clamp_int(payload.get("clip_id"), -1, -1, 10**9)

        if item is not None:
            rel = item.rel
            name = item.name
            url = VideoIndex._public_item(item)["url"]
            video_id = item.id
            clip_id = item.clip_id
        else:
            name = posixpath.basename(rel)
            url = "media/" + str(video_id) + "/" + urllib.parse.quote(name) if video_id >= 0 else ""

        if not rel:
            raise ValueError("Missing video id or relative path")

        verb = normalize_option(payload.get("verb"), VERB_OPTIONS, VERB_DEFAULT, VERB_ALIASES)
        noun = clean_text(payload.get("noun"), 200)
        taste_noun = clean_text(payload.get("taste_noun"), 200)
        scenario = normalize_option(payload.get("scenario"), SCENARIO_OPTIONS, SCENARIO_DEFAULT)
        condition = normalize_option(payload.get("condition"), CONDITION_OPTIONS, CONDITION_DEFAULT)

        now = time.time()
        record = {
            "id": video_id,
            "clip_id": clip_id,
            "rel": rel,
            "name": name,
            "url": url,
            "condition": condition,
            "verb": verb,
            "verb_display": verb,
            "scenario": scenario,
            "noun": noun,
            "noun_display": noun,
            "taste_noun": taste_noun,
            "taste_noun_display": taste_noun,
            "note": clean_text(payload.get("note"), 4000),
            "created_at": now,
            "updated_at": now,
            "updated_label": time.strftime("%Y-%m-%d %H:%M:%S", time.localtime(now)),
        }

        with self._lock:
            previous = self._items.get(rel)
            if previous and previous.get("created_at"):
                record["created_at"] = previous["created_at"]
            self._items[rel] = record
            self._persist_locked()
        return record

    def delete(self, rel: str) -> dict[str, Any] | None:
        rel = clean_text(rel, 4096)
        if not rel:
            return None
        with self._lock:
            record = self._items.pop(rel, None)
            if record is not None:
                self._persist_locked()
        return record

    def streamlined_payload(self) -> dict[str, Any]:
        """The exact structure written to the annotation JSON file: annotator id
        and name followed by the streamlined, marked-only annotations in gallery
        (clip_id) order. The "Download my log" export serves this same shape so
        the downloaded file matches the file saved on disk byte for byte."""
        with self._lock:
            return self._streamlined_payload_locked()

    def _streamlined_payload_locked(self) -> dict[str, Any]:
        records = sorted(
            (row for row in self._items.values() if record_has_marks(row)),
            key=lambda row: (clamp_int(row.get("clip_id"), 10**9, -1, 10**9), row.get("rel", "")),
        )
        return {
            "annotator_id": self.annotator["id"] if self.annotator else None,
            "annotator_name": self.annotator["name"] if self.annotator else None,
            "annotations": [streamlined_record(record) for record in records],
        }

    def _persist_locked(self) -> None:
        self.path.parent.mkdir(parents=True, exist_ok=True)
        payload = self._streamlined_payload_locked()
        temp_path = self.path.with_suffix(self.path.suffix + ".tmp")
        with temp_path.open("w", encoding="utf-8") as handle:
            # No sort_keys: annotator id + name land first, then the annotations.
            json.dump(payload, handle, indent=2)
        temp_path.replace(self.path)
        if self.backup_path is not None:
            try:
                self.backup_path.parent.mkdir(parents=True, exist_ok=True)
                tmp = self.backup_path.with_suffix(self.backup_path.suffix + ".tmp")
                with tmp.open("w", encoding="utf-8") as handle:
                    json.dump(payload, handle, indent=2)
                tmp.replace(self.backup_path)
            except Exception:
                pass  # never let a backup failure break the primary save

    def _build_txt_locked(self) -> str:
        all_records = sorted(self._items.values(), key=lambda row: clamp_int(row.get("id"), 0, -1, 10**9))
        records = [row for row in all_records if record_has_marks(row)]

        rows: list[list[str]] = []
        for record in records:
            clip_no = clamp_int(record.get("clip_id"), -1, -1, 10**9)
            label_no = str(clip_no) if clip_no >= 0 else str(clamp_int(record.get("id"), 0, -1, 10**9) + 1)
            rows.append([
                "#" + label_no + " - " + str(record.get("rel", "") or record.get("name", "")),
                str(record.get("condition", "")) or CONDITION_DEFAULT,
                str(record.get("verb_display", "")) or "N/A",
                str(record.get("scenario", "")) or SCENARIO_DEFAULT,
                str(record.get("noun_display", "")) or "N/A",
                str(record.get("taste_noun_display", "")) or "N/A",
            ])

        # Column-align: pad every field to the widest value in its column, plus a
        # 4-space gutter. The last column is left unpadded (no trailing spaces).
        ncols = 6
        widths = [max((len(row[col]) for row in rows), default=0) for col in range(ncols)]

        lines: list[str] = []
        for row in rows:
            lines.append(
                "".join(row[col].ljust(widths[col] + 4) for col in range(ncols - 1))
                + row[ncols - 1]
            )
        lines.append("")
        return "\n".join(lines)

    @staticmethod
    def _normalize_record(row: dict[str, Any]) -> dict[str, Any]:
        now = time.time()
        # Streamlined files store "file_name"; legacy files store "rel"/"name".
        rel = clean_text(row.get("rel") or row.get("file_name") or row.get("name"), 4096)
        name = clean_text(row.get("name") or row.get("file_name"), 512) or posixpath.basename(rel)
        video_id = clamp_int(row.get("id"), -1, -1, 10**9)
        clip_id = clamp_int(row.get("clip_id"), -1, -1, 10**9)
        url = clean_text(row.get("url"), 4096)
        if not url and video_id >= 0 and name:
            url = "media/" + str(video_id) + "/" + urllib.parse.quote(name)

        # Verbs are fixed vocabularies; anything unrecognized falls back to blank
        # so the form shows its default rather than inventing a value.
        verb = normalize_option(
            row.get("smell_verb") or row.get("verb") or row.get("verb_display"),
            VERB_OPTIONS,
            "",
            VERB_ALIASES,
        )
        # Noun is free text (streamlined "smell_noun" / legacy "noun"/"noun_display").
        noun = clean_text(row.get("smell_noun") or row.get("noun") or row.get("noun_display"), 200)
        taste_noun = clean_text(row.get("taste_noun") or row.get("taste_noun_display"), 200)

        # Scenario is a fixed two-option vocabulary; anything unrecognized falls
        # back to the default.
        scenario = normalize_option(row.get("scenario"), SCENARIO_OPTIONS, SCENARIO_DEFAULT)

        # Condition is a fixed single-select vocabulary; anything unrecognized
        # (including v5's comma-joined multi-select values) falls back to the
        # default.
        condition = normalize_option(row.get("condition"), CONDITION_OPTIONS, CONDITION_DEFAULT)

        note = clean_text(row.get("note"), 4000)
        legacy_tags = row.get("tags")
        if isinstance(legacy_tags, list) and legacy_tags:
            cues = ", ".join(clean_text(tag, 80) for tag in legacy_tags if clean_text(tag, 80))
            if cues:
                note = (note + " " if note else "") + "[cues: " + cues + "]"
                note = note[:4000]

        return {
            "id": video_id,
            "clip_id": clip_id,
            "rel": rel,
            "name": name,
            "url": url,
            "condition": condition,
            "verb": verb,
            "verb_display": verb,
            "scenario": scenario,
            "noun": noun,
            "noun_display": noun,
            "taste_noun": taste_noun,
            "taste_noun_display": taste_noun,
            "note": note,
            "created_at": float(row.get("created_at", now) or now),
            "updated_at": float(row.get("updated_at", now) or now),
            "updated_label": clean_text(row.get("updated_label"), 64),
        }


class AnnotationRegistry:
    """One AnnotationStore per annotator, so several people can label against the
    same running server without their logs overwriting one another. Each person
    gets their own JSON file (``annotation_<id>_<name>.json``); stores are created
    lazily the first time an annotator saves or loads."""

    def __init__(self, base_dir: Path, root: Path) -> None:
        self.base_dir = base_dir.expanduser()
        self.root = root
        self._stores: dict[int, AnnotationStore] = {}
        self._lock = threading.Lock()

    def file_stem(self, annotator_id: int) -> str:
        slug = slugify(ANNOTATORS.get(annotator_id, "")) or ("annotator_" + str(annotator_id))
        # The ITERATION token namespaces each distribution round into its own file
        # (annotation_<iter>_<id>_<name>.json) so a new round never reopens the
        # previous round's log, and the "Download my log" export carries the token.
        iteration = slugify(ITERATION)
        prefix = "annotation_" + (iteration + "_" if iteration else "")
        return prefix + format(annotator_id, "02d") + "_" + slug

    def store_for(self, annotator_id: int) -> AnnotationStore:
        with self._lock:
            store = self._stores.get(annotator_id)
            if store is None:
                stem = self.file_stem(annotator_id)
                store = AnnotationStore(
                    self.base_dir / (stem + ".json"),
                    self.base_dir / (stem + ".txt"),
                    self.root,
                    annotator={"id": annotator_id, "name": annotator_name(annotator_id)},
                    backup_path=BACKUP_NOTES_DIR / (stem + ".json"),
                )
                store.load()
                self._stores[annotator_id] = store
            return store


def load_annotator(payload: dict[str, Any]) -> dict[str, Any] | None:
    """Recover the saved annotator from an annotation file, tolerating both the
    top-level annotator_id/annotator_name fields and a nested annotator object."""
    aid = payload.get("annotator_id")
    name = payload.get("annotator_name")
    nested = payload.get("annotator")
    if isinstance(nested, dict):
        if aid is None:
            aid = nested.get("id")
        if name is None:
            name = nested.get("name")
    if aid is None and not name:
        return None
    annotator_id = clamp_int(aid, 0, 0, 10**9)
    resolved = ANNOTATORS.get(annotator_id) or clean_text(name, 128)
    if not resolved:
        return None
    return {"id": annotator_id, "name": resolved}


def natural_sort_key(value: str) -> list[Any]:
    parts = re.split(r"(\d+)", value.lower())
    return [int(part) if part.isdigit() else part for part in parts]


def clean_text(value: Any, max_len: int) -> str:
    if value is None:
        return ""
    return str(value).replace("\x00", "").strip()[:max_len]


def record_has_marks(record: dict[str, Any]) -> bool:
    """A record is worth persisting once the annotator has filled any field.
    Saved records always carry the Verb and Scenario defaults, so in practice
    any clip the annotator has touched qualifies."""
    if str(record.get("condition") or "").strip():
        return True
    if str(record.get("verb_display") or record.get("verb") or "").strip():
        return True
    if str(record.get("scenario") or "").strip():
        return True
    if str(record.get("noun_display") or record.get("noun") or "").strip():
        return True
    if str(record.get("taste_noun_display") or record.get("taste_noun") or "").strip():
        return True
    if str(record.get("note") or "").strip():
        return True
    return False


def normalize_option(
    value: Any,
    options: tuple[str, ...],
    default: str,
    aliases: dict[str, str] | None = None,
) -> str:
    raw = clean_text(value, 160).lower()
    if not raw:
        return default
    for option in options:
        if raw == option.lower():
            return option
    if aliases and raw in aliases:
        return aliases[raw]
    return default


def option_display(choice: str, other: str) -> str:
    if choice == "Other":
        return other or "Other"
    return choice


def option_from_display(value: Any, options: tuple[str, ...]) -> tuple[str, str]:
    """Inverse of ``option_display``: turn a stored display value back into a
    (choice, other) pair. A value that isn't one of the canonical options is
    treated as free-text under "Other"."""
    raw = clean_text(value, 200)
    if not raw:
        return "", ""
    for option in options:
        if raw.lower() == option.lower():
            return ("Other", "") if option == "Other" else (option, "")
    return "Other", raw


def streamlined_record(record: dict[str, Any]) -> dict[str, Any]:
    """Project a full in-memory record down to the fields persisted on disk.
    Insertion order here is the field order that lands in annotation.json."""
    return {
        "clip_id": clamp_int(record.get("clip_id"), -1, -1, 10**9),
        "file_name": record.get("name", "") or record.get("rel", ""),
        "condition": record.get("condition", CONDITION_DEFAULT) or CONDITION_DEFAULT,
        "smell_verb": record.get("verb_display", "") or "",
        "smell_noun": record.get("noun_display", "") or "",
        "scenario": record.get("scenario", SCENARIO_DEFAULT) or SCENARIO_DEFAULT,
        "taste_noun": record.get("taste_noun_display", "") or "",
    }


def clamp_int(value: Any, default: int, low: int, high: int) -> int:
    try:
        number = int(value)
    except (TypeError, ValueError):
        number = default
    return min(max(number, low), high)


def default_manifest_path(root: Path) -> Path:
    digest = hashlib.sha1(str(root.expanduser().resolve()).encode("utf-8")).hexdigest()[:16]
    return Path.home() / ".cache" / "video_gallery" / (digest + ".json")


def default_notes_path(root: Path) -> Path:
    digest = hashlib.sha1(str(root.expanduser().resolve()).encode("utf-8")).hexdigest()[:16]
    return Path.home() / ".cache" / "video_gallery" / (digest + "_smell_notes.json")


def default_annotation_path() -> Path:
    # Lives next to this script, i.e. in the same folder you have open in VS Code.
    try:
        return Path(__file__).resolve().parent / "annotation.json"
    except NameError:
        return Path.cwd() / "annotation.json"


def default_exemplars_path() -> Path:
    # Lives next to this script, i.e. in the same folder you have open in VS Code.
    try:
        return Path(__file__).resolve().parent / "smell_exemplars.txt"
    except NameError:
        return Path.cwd() / "smell_exemplars.txt"


def format_bytes(value: int) -> str:
    amount = float(value)
    for unit in ("B", "KB", "MB", "GB", "TB", "PB"):
        if amount < 1024 or unit == "PB":
            if unit == "B":
                return str(int(amount)) + " " + unit
            return format(amount, ".1f") + " " + unit
        amount /= 1024
    return str(value) + " B"


def json_response(handler: BaseHTTPRequestHandler, payload: Any, status: HTTPStatus = HTTPStatus.OK) -> None:
    body = json.dumps(payload).encode("utf-8")
    handler.send_response(status)
    handler.send_header("Content-Type", "application/json; charset=utf-8")
    handler.send_header("Content-Length", str(len(body)))
    handler.send_header("Cache-Control", "no-store")
    handler.end_headers()
    if handler.command != "HEAD":
        handler.wfile.write(body)


def csv_response(handler: BaseHTTPRequestHandler, records: list[dict[str, Any]]) -> None:
    output = io.StringIO(newline="")
    fields = ["id", "clip_id", "rel", "name", "condition", "verb", "scenario", "noun", "taste_noun", "note", "updated_label"]
    writer = csv.DictWriter(output, fieldnames=fields)
    writer.writeheader()
    for record in records:
        writer.writerow({
            "id": record.get("id", ""),
            "clip_id": record.get("clip_id", ""),
            "rel": record.get("rel", ""),
            "name": record.get("name", ""),
            "condition": record.get("condition", ""),
            "verb": record.get("verb_display", ""),
            "scenario": record.get("scenario", ""),
            "noun": record.get("noun_display", ""),
            "taste_noun": record.get("taste_noun_display", ""),
            "note": record.get("note", ""),
            "updated_label": record.get("updated_label", ""),
        })
    body = output.getvalue().encode("utf-8")
    handler.send_response(HTTPStatus.OK)
    handler.send_header("Content-Type", "text/csv; charset=utf-8")
    handler.send_header("Content-Disposition", "attachment; filename=smell_sign_notes.csv")
    handler.send_header("Content-Length", str(len(body)))
    handler.end_headers()
    if handler.command != "HEAD":
        handler.wfile.write(body)


def text_response(
    handler: BaseHTTPRequestHandler,
    body: str,
    status: HTTPStatus = HTTPStatus.OK,
    content_type: str = "text/plain; charset=utf-8",
) -> None:
    encoded = body.encode("utf-8")
    handler.send_response(status)
    handler.send_header("Content-Type", content_type)
    handler.send_header("Content-Length", str(len(encoded)))
    handler.end_headers()
    if handler.command != "HEAD":
        handler.wfile.write(encoded)


def read_json_body(handler: BaseHTTPRequestHandler) -> dict[str, Any]:
    length = clamp_int(handler.headers.get("Content-Length"), 0, 0, 2 * 1024 * 1024)
    if length == 0:
        return {}
    body = handler.rfile.read(length)
    payload = json.loads(body.decode("utf-8"))
    if not isinstance(payload, dict):
        raise ValueError("JSON body must be an object")
    return payload


class GalleryHandler(BaseHTTPRequestHandler):
    server_version = "VideoGallery/3.1"
    protocol_version = "HTTP/1.1"
    disable_nagle_algorithm = True

    def log_message(self, fmt: str, *args: Any) -> None:
        # Per-request access logging floods the terminal (one line per page load
        # and per served clip), so it is suppressed entirely. Only the startup
        # summary is printed.
        return

    def do_GET(self) -> None:
        self.route()

    def do_HEAD(self) -> None:
        self.route()

    def do_POST(self) -> None:
        self.route()

    def do_DELETE(self) -> None:
        self.route()

    def route(self) -> None:
        parsed = urllib.parse.urlparse(self.path)
        path = parsed.path
        params = urllib.parse.parse_qs(parsed.query)

        if path == "/":
            text_response(self, build_html(self.video_index.stats()), content_type="text/html; charset=utf-8")
            return

        if path == "/api/videos":
            query = params.get("q", [""])[0]
            offset = clamp_int(params.get("offset", ["0"])[0], 0, 0, 10**9)
            limit = clamp_int(params.get("limit", [str(PAGE_SIZE)])[0], PAGE_SIZE, 1, 500)
            annotator_id = self.resolve_annotator_id(params)
            json_response(self, self.video_index.search(query, offset, limit, annotator_id))
            return

        if path == "/api/stats":
            stats = self.video_index.stats()
            stats["total_size"] = format_bytes(int(stats["total_bytes"]))
            json_response(self, stats)
            return

        if path == "/api/notes":
            self.handle_notes(params)
            return

        if path == "/api/export":
            self.handle_export(params)
            return

        if path.startswith("/media/"):
            self.serve_media(path)
            return

        if path.startswith("/example/"):
            self.serve_example(path)
            return

        if path.startswith("/poster/"):
            self.serve_poster(path)
            return

        text_response(self, "Not found", HTTPStatus.NOT_FOUND)

    @property
    def video_index(self) -> VideoIndex:
        return self.server.video_index

    @property
    def registry(self) -> AnnotationRegistry:
        return self.server.registry

    def resolve_annotator_id(self, params: dict[str, list[str]], payload: dict[str, Any] | None = None) -> int | None:
        """Pull the annotator id from the request (POST body wins over query
        string). Returns None when it is missing or not a known annotator, so
        callers can reject the request instead of writing to the wrong log."""
        raw: Any = None
        if payload is not None and payload.get("annotator_id") is not None:
            raw = payload.get("annotator_id")
        elif params.get("annotator_id"):
            raw = params["annotator_id"][0]
        annotator_id = clamp_int(raw, 0, 0, 10**9)
        if annotator_id in ANNOTATORS:
            return annotator_id
        return None

    def handle_notes(self, params: dict[str, list[str]]) -> None:
        if self.command in {"GET", "HEAD"}:
            annotator_id = self.resolve_annotator_id(params)
            if annotator_id is None:
                json_response(self, {"ok": False, "error": "Missing or invalid annotator_id"}, HTTPStatus.BAD_REQUEST)
                return
            json_response(self, self.registry.store_for(annotator_id).all())
            return
        if self.command == "POST":
            try:
                payload = read_json_body(self)
                annotator_id = self.resolve_annotator_id(params, payload)
                if annotator_id is None:
                    raise ValueError("Missing or invalid annotator_id")
                store = self.registry.store_for(annotator_id)
                record = store.save(payload, self.video_index)
            except (json.JSONDecodeError, ValueError) as exc:
                json_response(self, {"ok": False, "error": str(exc)}, HTTPStatus.BAD_REQUEST)
                return
            except OSError as exc:
                json_response(self, {"ok": False, "error": str(exc)}, HTTPStatus.INTERNAL_SERVER_ERROR)
                return
            json_response(self, {"ok": True, "item": record, "count": store.all()["count"]})
            return
        if self.command == "DELETE":
            annotator_id = self.resolve_annotator_id(params)
            if annotator_id is None:
                json_response(self, {"ok": False, "error": "Missing or invalid annotator_id"}, HTTPStatus.BAD_REQUEST)
                return
            store = self.registry.store_for(annotator_id)
            rel = params.get("rel", [""])[0]
            try:
                record = store.delete(rel)
            except OSError as exc:
                json_response(self, {"ok": False, "error": str(exc)}, HTTPStatus.INTERNAL_SERVER_ERROR)
                return
            json_response(self, {"ok": True, "deleted": record, "count": store.all()["count"]})
            return
        text_response(self, "Method not allowed", HTTPStatus.METHOD_NOT_ALLOWED)

    def handle_export(self, params: dict[str, list[str]]) -> None:
        annotator_id = self.resolve_annotator_id(params)
        if annotator_id is None:
            json_response(self, {"ok": False, "error": "Missing or invalid annotator_id"}, HTTPStatus.BAD_REQUEST)
            return
        store = self.registry.store_for(annotator_id)
        stem = self.registry.file_stem(annotator_id)
        records = store.all()["items"]
        fmt = params.get("format", ["json"])[0].lower()
        if fmt == "csv":
            csv_response(self, records)
            return
        if fmt == "txt":
            body = store.txt_body().encode("utf-8")
            self.send_response(HTTPStatus.OK)
            self.send_header("Content-Type", "text/plain; charset=utf-8")
            self.send_header("Content-Disposition", "attachment; filename=" + stem + ".txt")
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            if self.command != "HEAD":
                self.wfile.write(body)
            return
        # Serve the same streamlined shape that is written to disk, so a
        # downloaded log is identical to the annotation_<id>_<name>.json file.
        payload = store.streamlined_payload()
        body = json.dumps(payload, indent=2).encode("utf-8")
        self.send_response(HTTPStatus.OK)
        self.send_header("Content-Type", "application/json; charset=utf-8")
        self.send_header("Content-Disposition", "attachment; filename=" + stem + ".json")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        if self.command != "HEAD":
            self.wfile.write(body)

    def serve_media(self, request_path: str) -> None:
        match = re.match(r"^/media/(\d+)(?:/.*)?$", request_path)
        if not match:
            text_response(self, "Bad media URL", HTTPStatus.BAD_REQUEST)
            return

        video_id = int(match.group(1))
        source = self.video_index.media_source_for_id(video_id)
        if source is None:
            text_response(self, "Video not found", HTTPStatus.NOT_FOUND)
            return
        path, base_dir = source

        try:
            root = base_dir.resolve()
            resolved = path.resolve()
            if os.path.commonpath([str(root), str(resolved)]) != str(root):
                text_response(self, "Invalid media path", HTTPStatus.FORBIDDEN)
                return
            stat = resolved.stat()
            if not resolved.is_file():
                text_response(self, "Video not found", HTTPStatus.NOT_FOUND)
                return
        except (OSError, ValueError):
            text_response(self, "Video not found", HTTPStatus.NOT_FOUND)
            return

        self.stream_media_file(resolved, stat)

    def serve_example(self, request_path: str) -> None:
        """Serve an instruction-guide example clip by *file name* straight from
        the video root (e.g. ``/example/Foo_frame4.mp4``). Unlike /media, which
        is keyed by a clip's playlist id, this lets the fixed set of verb-example
        clips be referenced by name — they live in the same served directory as
        the annotation clips. The name is confined to the root so it can't escape
        via ``..`` or an absolute path."""
        match = re.match(r"^/example/(.+)$", request_path)
        if not match:
            text_response(self, "Bad example URL", HTTPStatus.BAD_REQUEST)
            return
        name = urllib.parse.unquote(match.group(1))
        # Reject anything that isn't a bare file name (no path separators, no
        # parent refs) before touching the filesystem.
        if "/" in name or "\\" in name or name in ("", ".", ".."):
            text_response(self, "Invalid example path", HTTPStatus.FORBIDDEN)
            return
        try:
            root = self.video_index.root.resolve()
            resolved = (root / name).resolve()
            if os.path.commonpath([str(root), str(resolved)]) != str(root):
                text_response(self, "Invalid example path", HTTPStatus.FORBIDDEN)
                return
            stat = resolved.stat()
            if not resolved.is_file():
                text_response(self, "Example not found", HTTPStatus.NOT_FOUND)
                return
        except (OSError, ValueError):
            text_response(self, "Example not found", HTTPStatus.NOT_FOUND)
            return

        self.stream_media_file(resolved, stat)

    def stream_media_file(self, resolved: Path, stat: "os.stat_result") -> None:
        """Stream a resolved video file with HTTP range support (shared by the
        /media and /example routes). The caller is responsible for resolving and
        confining ``resolved`` to an allowed directory before calling this."""
        size = stat.st_size
        content_type = mimetypes.guess_type(str(resolved))[0] or "application/octet-stream"
        range_header = self.headers.get("Range")

        if range_header:
            parsed_range = parse_range_header(range_header, size)
            if parsed_range is None:
                self.send_response(HTTPStatus.REQUESTED_RANGE_NOT_SATISFIABLE)
                self.send_header("Content-Range", "bytes */" + str(size))
                self.send_header("Accept-Ranges", "bytes")
                self.send_header("Content-Length", "0")
                self.end_headers()
                return
            start, end = parsed_range
            self.send_response(HTTPStatus.PARTIAL_CONTENT)
            self.send_header("Content-Type", content_type)
            self.send_header("Accept-Ranges", "bytes")
            self.send_header("Content-Range", "bytes " + str(start) + "-" + str(end) + "/" + str(size))
            self.send_header("Content-Length", str(end - start + 1))
            self.send_header("Cache-Control", "public, max-age=31536000, immutable")
            self.end_headers()
            if self.command != "HEAD":
                self.stream_file(resolved, start, end)
            return

        self.send_response(HTTPStatus.OK)
        self.send_header("Content-Type", content_type)
        self.send_header("Accept-Ranges", "bytes")
        self.send_header("Content-Length", str(size))
        self.send_header("Cache-Control", "public, max-age=31536000, immutable")
        self.end_headers()
        if self.command != "HEAD":
            self.stream_file(resolved, 0, size - 1)

    def serve_poster(self, request_path: str) -> None:
        """Serve the first-frame poster JPEG for a clip, generated on demand and
        cached in memory (see VideoIndex.poster_bytes_for_id). Returns 404 when no
        poster can be produced (e.g. ffmpeg missing); the client simply shows an
        empty tile in that case, so the grid degrades gracefully."""
        match = re.match(r"^/poster/(\d+)(?:/.*)?$", request_path)
        if not match:
            text_response(self, "Bad poster URL", HTTPStatus.BAD_REQUEST)
            return

        video_id = int(match.group(1))
        poster = self.video_index.poster_bytes_for_id(video_id)
        if not poster:
            text_response(self, "Poster not found", HTTPStatus.NOT_FOUND)
            return

        self.send_response(HTTPStatus.OK)
        self.send_header("Content-Type", "image/jpeg")
        self.send_header("Content-Length", str(len(poster)))
        self.send_header("Cache-Control", "public, max-age=31536000, immutable")
        self.end_headers()
        if self.command != "HEAD":
            try:
                self.wfile.write(poster)
            except (BrokenPipeError, ConnectionResetError):
                pass

    def stream_file(self, path: Path, start: int, end: int) -> None:
        remaining = end - start + 1
        try:
            with path.open("rb") as handle:
                # Try zero-copy kernel transfer first (Linux/macOS).
                if hasattr(os, "sendfile"):
                    try:
                        self.wfile.flush()
                        offset = start
                        while remaining > 0:
                            sent = os.sendfile(
                                self.connection.fileno(),
                                handle.fileno(),
                                offset,
                                min(CHUNK_SIZE, remaining),
                            )
                            if sent == 0:
                                break
                            offset += sent
                            remaining -= sent
                        return
                    except OSError:
                        pass  # Fall back to buffered copy below.
                handle.seek(end - remaining + 1)
                while remaining > 0:
                    chunk = handle.read(min(CHUNK_SIZE, remaining))
                    if not chunk:
                        break
                    self.wfile.write(chunk)
                    remaining -= len(chunk)
        except (BrokenPipeError, ConnectionResetError):
            return

class GalleryServer(ThreadingHTTPServer):
    daemon_threads = True
    allow_reuse_address = True

    def __init__(
        self,
        server_address: tuple[str, int],
        handler_class: type[BaseHTTPRequestHandler],
        video_index: VideoIndex,
        registry: AnnotationRegistry,
        quiet: bool,
    ) -> None:
        super().__init__(server_address, handler_class)
        self.video_index = video_index
        self.registry = registry
        self.quiet = quiet


def parse_range_header(header: str, size: int) -> tuple[int, int] | None:
    match = re.match(r"bytes=(\d*)-(\d*)$", header.strip())
    if not match or size < 1:
        return None

    start_text, end_text = match.groups()
    if not start_text and not end_text:
        return None

    if start_text:
        start = int(start_text)
        end = int(end_text) if end_text else size - 1
    else:
        suffix_length = int(end_text)
        if suffix_length == 0:
            return None
        start = max(size - suffix_length, 0)
        end = size - 1

    if start >= size or end < start:
        return None

    return start, min(end, size - 1)


